130	function syncWhoScene(progress: number): void {
131	  const textItems = Array.from(
132	    document.querySelectorAll<HTMLElement>(WHO_TEXT_SELECTOR),
133	  );
134	  if (textItems.length === 0) return;
135	
136	  const shouldShow = progress >= WHO_REVEAL_START && progress < WHO_REVEAL_END;
137	  if (mainSceneDomState.isWhoTextVisible === shouldShow) return;
138	  mainSceneDomState.isWhoTextVisible = shouldShow;
139	  mainSceneDomState.whoTextTimers = clearTimers(
140	    mainSceneDomState.whoTextTimers,
141	  );
142	
143	  const items = shouldShow ? textItems : textItems.slice().reverse();
144	  items.forEach((item, index) => {
145	    const timerId = window.setTimeout(
146	      () => {
147	        if (shouldShow) {
148	          TextReveal.setVisibleOn(item);
149	          return;
150	        }
151	        TextReveal.setVisibleOff(item);
152	      },
153	      index * WHO_REVEAL_STAGGER_SECONDS * 1000,
154	    );
155	    mainSceneDomState.whoTextTimers.push(timerId);
156	  });
157	}
