362	function syncContactHead(progress: number): void {
363	  const section = document.querySelector<HTMLElement>(CONTACT_SECTION_SELECTOR);
364	  const head = document.querySelector<HTMLElement>(CONTACT_HEAD_SELECTOR);
365	  const actions = document.querySelector<HTMLElement>(CONTACT_ACTIONS_SELECTOR);
366	  if (!section || !head || !actions) return;
367	  const textItems = Array.from(
368	    head.querySelectorAll<HTMLElement>(".mask-target"),
369	  );
370	  const actionItems = Array.from(
371	    document.querySelectorAll<HTMLElement>(CONTACT_ACTION_ITEM_SELECTOR),
372	  );
373	  // Keep the contact panel visible through the footer zone and hide it only
374	  // when the scene is left or rewound before the reveal threshold.
375	  const shouldShow = progress >= CONTACT_HEAD_TRANSITION.revealStart;
376	
377	  if (mainSceneDomState.isContactActionsVisible !== shouldShow) {
378	    mainSceneDomState.isContactActionsVisible = shouldShow;
379	    mainSceneDomState.contactActionTimers = clearTimers(
380	      mainSceneDomState.contactActionTimers,
381	    );
382	    const queue = shouldShow ? actionItems : actionItems.slice().reverse();
383	    const delayStep = shouldShow
384	      ? CONTACT_HEAD_TRANSITION.revealStagger
385	      : CONTACT_HEAD_TRANSITION.hideStagger;
386	    queue.forEach((item, index) => {
387	      const timerId = window.setTimeout(
388	        () => {
389	          item.classList.add(INIT_DOM_CLASSES.blockBase);
390	          item.classList.remove(INIT_DOM_CLASSES.boxHidden);
391	          if (shouldShow) {
392	            item.classList.remove("is-block-reveal-down");
393	            BlockReveal.reveal(item);
394	            return;
395	          }
396	          item.classList.remove(INIT_DOM_CLASSES.blockUp);
397	          item.classList.add("is-block-reveal-down");
398	        },
399	        index * delayStep * 1000,
400	      );
401	      mainSceneDomState.contactActionTimers.push(timerId);
402	    });
403	  }
404	
405	  if (mainSceneDomState.isContactHeadVisible === shouldShow) return;
406	  mainSceneDomState.isContactHeadVisible = shouldShow;
407	  mainSceneDomState.contactHeadTimers = clearTimers(
408	    mainSceneDomState.contactHeadTimers,
409	  );
410	
411	  if (shouldShow) {
412	    section.dataset.active = "true";
413	    head.dataset.active = "true";
414	    actions.dataset.active = "true";
415	    TextReveal.setVisibleOff(textItems);
416	    textItems.forEach((item, index) => {
417	      const timerId = window.setTimeout(
418	        () => {
419	          TextReveal.setVisibleOn(item);
420	        },
421	        index * CONTACT_HEAD_TRANSITION.revealStagger * 1000,
422	      );
423	      mainSceneDomState.contactHeadTimers.push(timerId);
424	    });
425	    return;
426	  }
427	
428	  textItems
429	    .slice()
430	    .reverse()
431	    .forEach((item, index) => {
432	      const timerId = window.setTimeout(
433	        () => {
434	          TextReveal.setVisibleOff(item);
435	        },
436	        index * CONTACT_HEAD_TRANSITION.hideStagger * 1000,
437	      );
438	      mainSceneDomState.contactHeadTimers.push(timerId);
439	    });
440	
441	  const hideTimerId = window.setTimeout(
442	    () => {
443	      section.dataset.active = "false";
444	      head.dataset.active = "false";
445	      actions.dataset.active = "false";
446	    },
447	    (Math.max(textItems.length - 1, 0) *
448	      CONTACT_HEAD_TRANSITION.hideStagger +
449	      CONTACT_HEAD_TRANSITION.hideSettleDuration) *
450	      1000,
451	  );
452	  mainSceneDomState.contactHeadTimers.push(hideTimerId);
453	}
