41	/**
42	 * Creates a PlaneGeometry whose vertices are bent cylindrically around the Y-axis,
43	 * so the card's edges curve inward toward the planet (local -Z = radially inward).
44	 * Each vertex at local x=lx is moved to arc position on a cylinder of curveRadius:
45	 *   newX = curveRadius * sin(lx / curveRadius)
46	 *   newZ = -curveRadius * (1 - cos(lx / curveRadius))   ← negative = toward planet
47	 */
48	function createCurvedCardGeometry(
49	  width: number,
50	  height: number,
51	  curveRadius: number,
52	): THREE.BufferGeometry {
53	  const geo = new THREE.PlaneGeometry(width, height, 20, 1);
54	  const pos = geo.attributes.position as THREE.BufferAttribute;
55	  for (let i = 0; i < pos.count; i++) {
56	    const lx = pos.getX(i);
57	    const dAngle = lx / curveRadius;
58	    pos.setX(i, curveRadius * Math.sin(dAngle));
59	    pos.setZ(i, -curveRadius * (1.0 - Math.cos(dAngle)));
60	  }
61	  pos.needsUpdate = true;
62	  geo.computeVertexNormals();
63	  return geo;
64	}
