84	function createCardMaterial(
85	  texture: THREE.Texture | null,
86	  color: number,
87	): THREE.MeshBasicMaterial {
88	  const mat = new THREE.MeshBasicMaterial({
89	    map: texture ?? null,
90	    color: texture ? 0xffffff : color,
91	    side: THREE.DoubleSide,
92	  });
93	
94	  if (texture) {
95	    // Flip UV.x on back face so back-side texture is not mirrored
96	    mat.onBeforeCompile = (shader) => {
97	      shader.fragmentShader = shader.fragmentShader.replace(
98	        "vec4 sampledDiffuseColor = texture2D( map, vMapUv );",
99	        `vec2 _uv = gl_FrontFacing ? vMapUv : vec2(1.0 - vMapUv.x, vMapUv.y);
100	        vec4 sampledDiffuseColor = texture2D( map, _uv );`,
101	      );
102	    };
103	    mat.needsUpdate = true;
104	  }
105	
106	  return mat;
107	}
