109	function selectProofItems(items: WorkApiItem[], max: number): WorkApiItem[] {
110	  const awardedVideo = items.filter((i) => i.isAwarded && i.thumbnailVideo);
111	  const awardedImage = items.filter((i) => i.isAwarded && !i.thumbnailVideo && i.thumbnailImage);
112	  const otherVideo   = items.filter((i) => !i.isAwarded && i.thumbnailVideo);
113	  const otherImage   = items.filter((i) => !i.isAwarded && !i.thumbnailVideo && i.thumbnailImage);
114	
115	  const result: WorkApiItem[] = [...awardedVideo];
116	  if (result.length < max) result.push(...awardedImage);
117	  if (result.length < max) result.push(...otherVideo);
118	  if (result.length < max) result.push(...otherImage);
119	  return result.slice(0, max);
120	}
