29	export class ObserveManager {
30	  private readonly _observers = new Set<IntersectionObserver>();
31	  private readonly _stateByTarget = new Map<Element, boolean>();
32	  private readonly _onceTargets = new Set<Element>();
33	  private _cleanupDirectional: (() => void) | null = null;
34	  private _direction: ScrollDirection = "idle";
35	  private _lastScrollY = 0;
36	  private _rafId: number | null = null;
37	
38	  observe(
39	    targets: Element[],
40	    handlers: InviewObserverHandlers,
41	    options: TextRevealInitOptions = {},
42	  ): void {
43	    this.dispose();
44	    if (targets.length === 0) return;
45	
46	    const observerEnabled =
47	      options.observerEnabled ?? OBSERVE_DEFAULTS.enabled;
48	    const revealWithoutObserver =
49	      OBSERVE_DEFAULTS.revealWhenObserverDisabled;
50	
51	    if (!observerEnabled) {
52	      if (revealWithoutObserver) this._runCallback(targets, handlers.onEnter);
53	      return;
54	    }
55	
56	    const shouldUseIntersectionObserver =
57	      options.rootMargin != null || options.threshold != null;
58	    if (shouldUseIntersectionObserver) {
59	      this._observeWithIntersectionObserver(targets, handlers, options);
60	      return;
61	    }
62	
63	    this._observeWithDirectionalBounds(targets, handlers, options);
64	  }
65	
66	  dispose(): void {
67	    this._observers.forEach((observer) => observer.disconnect());
68	    this._observers.clear();
69	    this._cleanupDirectional?.();
70	    this._cleanupDirectional = null;
71	    if (this._rafId != null) {
72	      window.cancelAnimationFrame(this._rafId);
73	      this._rafId = null;
74	    }
75	    this._stateByTarget.clear();
76	    this._onceTargets.clear();
77	    this._direction = "idle";
78	    this._lastScrollY = 0;
79	  }
80	
81	  private _observeWithIntersectionObserver(
82	    targets: Element[],
83	    handlers: InviewObserverHandlers,
84	    options: TextRevealInitOptions,
85	  ): void {
86	    const revealWithoutApi = OBSERVE_DEFAULTS.revealWhenObserverUnavailable;
87	    if (typeof IntersectionObserver === "undefined") {
88	      if (revealWithoutApi) this._runCallback(targets, handlers.onEnter);
89	      return;
90	    }
91	
92	    const observeOnce = options.observeOnce ?? OBSERVE_DEFAULTS.once;
93	    const observer = new IntersectionObserver(
94	      (entries) => {
95	        for (const entry of entries) {
96	          if (entry.isIntersecting) {
97	            handlers.onEnter(entry.target);
98	            if (observeOnce) observer.unobserve(entry.target);
99	            continue;
100	          }
101	          handlers.onLeave?.(entry.target);
102	        }
103	      },
104	      {
105	        threshold: options.threshold ?? OBSERVE_DEFAULTS.threshold,
106	        rootMargin: options.rootMargin ?? OBSERVE_DEFAULTS.rootMargin,
107	      },
108	    );
109	
110	    targets.forEach((target) => observer.observe(target));
111	    this._observers.add(observer);
112	  }
113	
114	  private _observeWithDirectionalBounds(
115	    targets: Element[],
116	    handlers: InviewObserverHandlers,
117	    options: TextRevealInitOptions,
118	  ): void {
119	    if (typeof window === "undefined") {
120	      this._runCallback(targets, handlers.onEnter);
121	      return;
122	    }
123	
124	    const observeOnce = options.observeOnce ?? OBSERVE_DEFAULTS.once;
125	    this._lastScrollY = window.scrollY;
126	    targets.forEach((target) => this._stateByTarget.set(target, false));
127	
128	    const update = (): void => {
129	      this._rafId = null;
130	      const nextScrollY = window.scrollY;
131	      this._direction = this._resolveDirection(nextScrollY);
132	      this._lastScrollY = nextScrollY;
133	      const viewportHeight =
134	        ResponsiveRuntime.getDefault().getSnapshot().viewportHeight;
135	
136	      targets.forEach((target) => {
137	        if (observeOnce && this._onceTargets.has(target)) return;
138	        const wasVisible = this._stateByTarget.get(target) ?? false;
139	        const isVisible = this._isTargetVisible(target, viewportHeight);
140	        if (wasVisible === isVisible) return;
141	        this._stateByTarget.set(target, isVisible);
142	        if (isVisible) {
143	          handlers.onEnter(target);
144	          if (observeOnce) this._onceTargets.add(target);
145	          return;
146	        }
147	        handlers.onLeave?.(target);
148	      });
149	    };
150	
151	    const scheduleUpdate = (): void => {
152	      if (this._rafId != null) return;
153	      this._rafId = window.requestAnimationFrame(update);
154	    };
155	
156	    const onScroll = (): void => scheduleUpdate();
157	    const onResize = (): void => scheduleUpdate();
158	
159	    window.addEventListener("scroll", onScroll, { passive: true });
160	    window.addEventListener("resize", onResize, { passive: true });
161	    this._cleanupDirectional = () => {
162	      window.removeEventListener("scroll", onScroll);
163	      window.removeEventListener("resize", onResize);
164	    };
165	
166	    update();
167	  }
168	
169	  private _resolveDirection(nextScrollY: number): ScrollDirection {
170	    if (nextScrollY > this._lastScrollY) return "down";
171	    if (nextScrollY < this._lastScrollY) return "up";
172	    return "idle";
173	  }
174	
175	  private _isTargetVisible(target: Element, viewportHeight: number): boolean {
176	    const rect = target.getBoundingClientRect();
177	
178	    if (this._direction === "down") {
179	      return (
180	        rect.top <=
181	          viewportHeight * (1 + DIRECTIONAL_BOUNDS.down.enterBottomExpandRatio) &&
182	        rect.bottom >=
183	          viewportHeight * DIRECTIONAL_BOUNDS.down.leaveTopCutoffRatio
184	      );
185	    }
186	
187	    if (this._direction === "up") {
188	      return (
189	        rect.bottom >=
190	          viewportHeight * -DIRECTIONAL_BOUNDS.up.enterTopExpandRatio &&
191	        rect.top <=
192	          viewportHeight * (1 - DIRECTIONAL_BOUNDS.up.leaveBottomCutoffRatio)
193	      );
194	    }
195	
196	    return rect.top <= viewportHeight && rect.bottom >= 0;
197	  }
198	
199	  private _runCallback(
200	    targets: Element[],
201	    callback: InviewObserverCallback,
202	  ): void {
203	    targets.forEach((target) => callback(target));
204	  }
205	}
