private _observeWithIntersectionObserver(
  targets: Element[],
  handlers: InviewObserverHandlers,
  options: TextRevealInitOptions,
): void {
  const observer = new IntersectionObserver(
    (entries) => {
      for (const entry of entries) {
        if (entry.isIntersecting) {
          handlers.onEnter(entry.target);
          if (observeOnce) observer.unobserve(entry.target);
          continue;
        }
        handlers.onLeave?.(entry.target);
      }
    },
    {
      threshold: options.threshold ?? OBSERVE_DEFAULTS.threshold,
      rootMargin: options.rootMargin ?? OBSERVE_DEFAULTS.rootMargin,
    },
  );
  targets.forEach((target) => observer.observe(target));
  this._observers.add(observer);
}

